## server-vulnerable.js — Target Without CSRF Protection

```javascript
/**
 * VULNERABLE SERVER - No CSRF protection
 *
 * Educational purposes only. Demonstrates what happens when
 * state-changing endpoints lack CSRF defenses.
 *
 * Run on port 3001: node server-vulnerable.js
 */

const express = require("express");
const cookieParser = require("cookie-parser");
const session = require("express-session");
const path = require("path");

const app = express();
const PORT = 3001;

// --- Middleware ---
app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(cookieParser());
app.use(
  session({
    secret: "vulnerable-secret-do-not-use-in-prod",
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      // SameSite intentionally omitted to allow cross-site requests
      // This is the misconfiguration that enables CSRF
      sameSite: false,
    },
  })
);

// --- In-memory "database" ---
const users = {
  alice: { password: "password123", email: "alice@example.com", balance: 1000 },
};

const auditLog = [];

function log(entry) {
  const record = { timestamp: new Date().toISOString(), ...entry };
  auditLog.push(record);
  console.log("[AUDIT]", JSON.stringify(record));
}

// --- Auth middleware ---
function requireAuth(req, res, next) {
  if (!req.session.user) {
    return res.status(401).json({ error: "Not authenticated" });
  }
  next();
}

// --- Routes ---

// Serve the login page
app.get("/", (req, res) => {
  res.sendFile(path.join(__dirname, "public", "victim-login.html"));
});

// Login
app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = users[username];

  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  req.session.user = username;
  log({ event: "LOGIN", user: username, ip: req.ip });
  res.json({ success: true, message: `Logged in as ${username}` });
});

// Logout
app.post("/logout", (req, res) => {
  const user = req.session.user;
  req.session.destroy();
  log({ event: "LOGOUT", user });
  res.json({ success: true });
});

// Get account info (safe - read-only)
app.get("/account", requireAuth, (req, res) => {
  const username = req.session.user;
  const user = users[username];
  res.json({
    username,
    email: user.email,
    balance: user.balance,
  });
});

/**
 * VULNERABLE ENDPOINT: Transfer funds
 *
 * No CSRF token check. Any site can trigger this on behalf
 * of an authenticated user by submitting a cross-origin form.
 */
app.post("/transfer", requireAuth, (req, res) => {
  const { to, amount } = req.body;
  const username = req.session.user;
  const user = users[username];
  const transferAmount = parseFloat(amount);

  if (!to || isNaN(transferAmount) || transferAmount <= 0) {
    return res.status(400).json({ error: "Invalid transfer parameters" });
  }

  if (user.balance < transferAmount) {
    return res.status(400).json({ error: "Insufficient funds" });
  }

  user.balance -= transferAmount;

  log({
    event: "TRANSFER",
    from: username,
    to,
    amount: transferAmount,
    // Note: no Origin/Referer validation either
    origin: req.headers.origin || "none",
    referer: req.headers.referer || "none",
  });

  res.json({
    success: true,
    message: `Transferred $${transferAmount} to ${to}`,
    newBalance: user.balance,
  });
});

/**
 * VULNERABLE ENDPOINT: Change email
 *
 * Same issue — no CSRF protection on account modification.
 */
app.post("/change-email", requireAuth, (req, res) => {
  const { email } = req.body;
  const username = req.session.user;

  if (!email || !email.includes("@")) {
    return res.status(400).json({ error: "Invalid email" });
  }

  const oldEmail = users[username].email;
  users[username].email = email;

  log({
    event: "EMAIL_CHANGE",
    user: username,
    oldEmail,
    newEmail: email,
    origin: req.headers.origin || "none",
  });

  res.json({ success: true, message: `Email changed to ${email}` });
});

// Audit log viewer (for research observation)
app.get("/audit-log", (req, res) => {
  res.json(auditLog);
});

app.listen(PORT, () => {
  console.log(`\n[VULNERABLE SERVER] Running on http://localhost:${PORT}`);
  console.log("  This server has NO CSRF protection.");
  console.log("  Use for research observation only.\n");
});
```

## server-protected.js — Target With CSRF Protection

```javascript
/**
 * PROTECTED SERVER - Full CSRF defenses applied
 *
 * Demonstrates the synchronizer token pattern, SameSite cookies,
 * and Origin/Referer header validation working together.
 *
 * Run on port 3002: node server-protected.js
 */

const express = require("express");
const cookieParser = require("cookie-parser");
const session = require("express-session");
const csrf = require("csurf");
const { v4: uuidv4 } = require("uuid");

const app = express();
const PORT = 3002;

// --- Middleware ---
app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(cookieParser());
app.use(
  session({
    secret: uuidv4(), // Random secret per process start
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      sameSite: "strict", // Defense layer 1: SameSite=Strict
      // secure: true  // Enable this in production (requires HTTPS)
    },
  })
);

// Defense layer 2: Synchronizer token pattern via csurf
const csrfProtection = csrf({ cookie: false }); // Token stored in session, not cookie

// --- In-memory "database" ---
const users = {
  alice: { password: "password123", email: "alice@example.com", balance: 1000 },
};

const auditLog = [];

function log(entry) {
  const record = { timestamp: new Date().toISOString(), ...entry };
  auditLog.push(record);
  console.log("[AUDIT]", JSON.stringify(record));
}

// --- Defense layer 3: Origin/Referer validation ---
function validateOrigin(req, res, next) {
  const origin = req.headers.origin;
  const referer = req.headers.referer;
  const allowedOrigin = `http://localhost:${PORT}`;

  // Allow requests with no origin header only from same-origin navigations
  if (!origin && !referer) {
    // Could be a direct form post — allow but log
    log({ event: "ORIGIN_MISSING", path: req.path, ip: req.ip });
    return next();
  }

  const sourceOrigin = origin || (referer ? new URL(referer).origin : null);

  if (sourceOrigin && sourceOrigin !== allowedOrigin) {
    log({
      event: "ORIGIN_REJECTED",
      path: req.path,
      sourceOrigin,
      ip: req.ip,
    });
    return res.status(403).json({
      error: "Forbidden: cross-origin request rejected",
      detail: `Expected origin ${allowedOrigin}, got ${sourceOrigin}`,
    });
  }

  next();
}

// --- Auth middleware ---
function requireAuth(req, res, next) {
  if (!req.session.user) {
    return res.status(401).json({ error: "Not authenticated" });
  }
  next();
}

// --- Routes ---

// Provide CSRF token to the frontend
app.get("/csrf-token", csrfProtection, (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// Login (no CSRF needed — user isn't authenticated yet)
app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = users[username];

  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Regenerate session on login to prevent session fixation
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: "Session error" });
    req.session.user = username;
    log({ event: "LOGIN", user: username, ip: req.ip });
    res.json({ success: true, message: `Logged in as ${username}` });
  });
});

// Logout
app.post("/logout", requireAuth, csrfProtection, (req, res) => {
  const user = req.session.user;
  req.session.destroy();
  log({ event: "LOGOUT", user });
  res.json({ success: true });
});

// Get account info
app.get("/account", requireAuth, (req, res) => {
  const username = req.session.user;
  const user = users[username];
  res.json({ username, email: user.email, balance: user.balance });
});

/**
 * PROTECTED ENDPOINT: Transfer funds
 *
 * All three defenses active:
 *   1. SameSite=Strict cookie
 *   2. CSRF synchronizer token (csurf middleware)
 *   3. Origin header validation
 */
app.post(
  "/transfer",
  requireAuth,
  validateOrigin,
  csrfProtection,
  (req, res) => {
    const { to, amount } = req.body;
    const username = req.session.user;
    const user = users[username];
    const transferAmount = parseFloat(amount);

    if (!to || isNaN(transferAmount) || transferAmount <= 0) {
      return res.status(400).json({ error: "Invalid transfer parameters" });
    }

    if (user.balance < transferAmount) {
      return res.status(400).json({ error: "Insufficient funds" });
    }

    user.balance -= transferAmount;

    log({
      event: "TRANSFER",
      from: username,
      to,
      amount: transferAmount,
      csrfValidated: true,
    });

    res.json({
      success: true,
      message: `Transferred $${transferAmount} to ${to}`,
      newBalance: user.balance,
    });
  }
);

/**
 * PROTECTED ENDPOINT: Change email
 */
app.post(
  "/change-email",
  requireAuth,
  validateOrigin,
  csrfProtection,
  (req, res) => {
    const { email } = req.body;
    const username = req.session.user;

    if (!email || !email.includes("@")) {
      return res.status(400).json({ error: "Invalid email" });
    }

    const oldEmail = users[username].email;
    users[username].email = email;

    log({
      event: "EMAIL_CHANGE",
      user: username,
      oldEmail,
      newEmail: email,
      csrfValidated: true,
    });

    res.json({ success: true, message: `Email changed to ${email}` });
  }
);

// CSRF error handler — catches token mismatch
app.use((err, req, res, next) => {
  if (err.code === "EBADCSRFTOKEN") {
    log({
      event: "CSRF_ATTACK_BLOCKED",
      path: req.path,
      origin: req.headers.origin || "none",
      referer: req.headers.referer || "none",
      ip: req.ip,
    });
    return res.status(403).json({
      error: "CSRF token validation failed",
      detail: "Request blocked. Invalid or missing CSRF token.",
    });
  }
  next(err);
});

// Audit log viewer
app.get("/audit-log", (req, res) => {
  res.json(auditLog);
});

app.listen(PORT, () => {
  console.log(`\n[PROTECTED SERVER] Running on http://localhost:${PORT}`);
  console.log("  CSRF defenses: SameSite cookie + sync token + Origin check");
  console.log("  Attacks against this server will be blocked and logged.\n");
});
```

